import sqlite3
import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("lms")


@mcp.tool()
def refund_and_move_student_enrollment(enrollment_id: str, target_course_id: str, refund_cents: int) -> dict:
    con = sqlite3.connect("lms.db")
    row = con.execute(
        "SELECT payment_intent FROM enrollments WHERE id = ?", (enrollment_id,)
    ).fetchone()
    if row is None:
        con.close()
        return {"ok": False, "error": "enrollment not found"}
    refund = stripe.Refund.create(payment_intent=row[0], amount=refund_cents)
    con.execute("UPDATE enrollments SET course_id = ? WHERE id = ?", (target_course_id, enrollment_id))
    con.commit()
    con.close()
    return {"ok": True, "refund_id": refund.id, "refunded_cents": refund_cents, "new_course_id": target_course_id}
